 , @debug_mode='F'

 */

CREATE PROCEDURE [dbo].[SCP0009_GET_SHIPMENT_PLAN_FG]
--CREATE PROCEDURE [dbo].[SCP0009_GET_SHIPMENT_PLAN_FG]
	@p_from_yyyymmdd		NVARCHAR(8),
	@p_to_yyyymmdd			NVARCHAR(8),
	@p_division_id			NVARCHAR(30),
	@p_biz_type				NVARCHAR(30),
	@p_project_code			NVARCHAR(MAX),
	@p_item_id				NVARCHAR(MAX),
	@p_electype				NVARCHAR(30) ,
	@p_plan_start_yyyymmdd  NVARCHAR(8),
	@p_plan_type			NVARCHAR(10),
	@p_seq					NVARCHAR(10),
	@p_fromsite				NVARCHAR(MAX),
	@p_team_id              NVARCHAR(MAX),
	@p_tosite				NVARCHAR(MAX),
	@p_bucket				NVARCHAR(10),	-- 2021.10.05 : UI 속도 개선 (bucket 별 컬럼 설정 변경하여 조회되도록 수정 함)
	@p_to_period			NVARCHAR(8),	-- 2021.10.05 : UI 속도 개선 (bucket 별 컬럼 설정 변경하여 조회되도록 수정 함)
	@p_chk_all				NVARCHAR(1), -- 2021.11.24 :  체크 시 bucket='daily' 조회
	@p_program_id			NVARCHAR(10) = 'SCP0009' ,
	@p_sheet_name			NVARCHAR(30) = 'Shipment Plan FG' ,
	@p_user_id				NVARCHAR(30),
	@debug_mode             NVARCHAR(1) ='F'
AS
B

EGIN
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SET NOCOUNT ON; 



	--DECLARE @p_from_yyyymmdd		NVARCHAR(8)		= N'20240101';
	--DECLARE @p_to_yyyymmdd			NVARCHAR(8)		= N'20250223';
	--DECLARE @p_division_id			NVARCHAR(10)	= N'40';
	--DECLARE @p_biz_type				NVARCHAR(10)	= N'P';
	--DECLARE @p_project_code			NVARCHAR(max)	= N'';
	--DECLARE @p_item_id				NVARCHAR(max)	= N'';
	--DECLARE @p_electype				NVARCHAR(30)	= N'';
	--DECLARE @p_plan_start_yyyymmdd	NVARCHAR(8)		= N'20240226';
	--DECLARE @p_plan_type			NVARCHAR(50)	= N'MA';
	--DECLARE @p_seq					NVARCHAR(50)	= N'1';
	--DECLARE @p_fromsite				NVARCHAR(MAX)	= N'';
	--DECLARE @p_team_id				NVARCHAR(MAX)	= N'';
	--DECLARE @p_tosite				NVARCHAR(MAX)	= N'';
	--DECLARE @p_bucket				NVARCHAR(30)	= N'DAILY';
 --   DECLARE @p_to_period			NVARCHAR(8)		= N'20250223';
	--DECLARE @p_chk_all				NVARCHAR(1)		= N'N';
	--DECLARE @p_program_id			NVARCHAR(30)	= N'SCP0009';
	--DECLARE @p_sheet_name			NVARCHAR(30)	= N'Shipment Plan FG';
	--DECLARE @p_user_id				NVARCHAR(30)	= N'iamarock';
	--DECLARE @debug_mode				NVARCHAR(1)		= N'F';


    DECLARE @V_ELAPSED_TIME_BEG             DATETIME            = CURRENT_TIMESTAMP;


	declare @v_data_cnt nvarchar(8);
	set @v_data_cnt =0;

	DECLARE @v_cnt_usr_measure	INTEGER =0;
	DECLARE @v_from_yyyymmdd     AS NVARCHAR(8);
	DECLARE @v_to_yyyymmdd       AS NVARCHAR(8);
	DECLARE @v_from_result       AS NVARCHAR(8);
	DECLARE @v_to_result         AS NVARCHAR(8);
	DECLARE @v_min_yyyymmdd      AS NVARCHAR(8);   -- 2021/07/21	
	DECLARE @v_RSLT_FLAG AS NVARCHAR(1) = 'Y';   -- 2021/07/21
	DECLARE @DIV_ENERGY  AS NVARCHAR(MAX) = '82';

	SET @v_cnt_usr_measure = (
								SELECT COUNT(*)
								FROM scm_mst_titleset_user
								WHERE 1=1
								 AND program_id  =  @p_program_id
								 AND sheet_name  =  @p_sheet_name
								 AND user_id     =  @p_user_id
							  )    

	SET @v_from_yyyymmdd = '';
	SET @v_to_yyyymmdd   = '';
	SET @v_from_result   = '';
	SET @v_to_result     = '';

	  SELECT @v_from_yyyymmdd = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_plan_start_yyyymmdd

	  SELECT @v_from_result = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_from_yyyymmdd;

	  SELECT @v_to_result = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_to_yyyymmdd;

	  IF @v_from_yyyymmdd > @v_from_result
		  BEGIN -- 실적 보여줌		  
		  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
		  SET @v_to_result     = @v_from_yyyymmdd;
		  END;
	  ELSE IF @v_from_yyyymmdd <= @v_from_result
		  BEGIN -- 실적 없음
		  
		  SET @v_RSLT_FLAG = 'N';  -- 2021/07/21 // 계획만 조회
		  
		  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
		  SET @v_from_result = CONVERT(CHAR(8), DATEADD(MM, 6, convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_to_result = CONVERT(CHAR(8), DATEADD(MM, -6, convert(datetime,@p_plan_start_yyyymmdd)), 112)
		  END;
	  ELSE IF @v_from_yyyymmdd > @v_to_result
		  BEGIN
		  SET @v_from_yyyymmdd = CONVERT(CHAR(8), DATEADD(MM, -6,  convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_to_yyyymmdd = CONVERT(CHAR(8), DATEADD(MM, -6,  convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_from_result = @p_from_yyyymmdd;
		  SET @v_to_result = @p_to_yyyymmdd;
		  END;
	  ELSE IF @v_from_yyyymmdd = @v_to_result
		  BEGIN
		  SET @v_to_yyyymmdd = @v_from_yyyymmdd
		  SET @v_from_result = @p_from_yyyymmdd;
		  SET @v_to_result = @p_to_yyyymmdd;
		  END;

	 IF @debug_mode ='T'
		BEGIN
			PRINT '----------------------------------';
			PRINT 'v_from_yyyymmdd =' +@v_from_yyyymmdd;
			PRINT 'v_to_yyyymmdd =' +@v_to_yyyymmdd;
			PRINT 'v_from_result =' +@v_from_result;
			PRINT 'v_to_result =' +@v_to_result	;
			PRINT '----------------------------------';
		END;

    DECLARE @arr_project_code

_order_no  ;

			SET @mEXEC = '';

			-- 20230411 ENERGY (UI 셀병합 위해서 문자열 AND Null일 경우 공백으로 처리 필요)
			SET @mEXEC = @mEXEC+'      ;WITH W_ENERGY AS (
			                                              SELECT ITEM_ID 
														       , convert(nvarchar(max), Convert(numeric(13,4),MAX(ENERGE))) AS ENERGY 
															FROM SCM_ITEM_M_SN WITH(NOLOCK)  
														   WHERE ENERGE IS NOT NULL 
														     AND ENERGE != '''' 
													    GROUP BY ITEM_ID)		
						'+CHAR(10); 
			SET @mEXEC = @mEXEC+'      SELECT a.*																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , ISNULL(b.PROJECT_NAME, ''-'') PROJECT_NAME								'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , ISNULL(EG.ENERGY,'' '') AS ENERGY								                        '+CHAR(10);	
			--@p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'			  , ISNULL(CASE WHEN a.division_id <> ''40'' and a.division_id <> ''82'' THEN b.PROJECT_OWNER ELSE f.USER_NAME_EN end, ''-'') AS PROJECT_OWNER												'+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+'			  , ISNULL(CASE WHEN a.origin_to_division_id <> ''40'' and a.division_id <> ''82'' THEN b.PROJECT_OWNER ELSE f.USER_NAME_EN end, ''-'') AS PROJECT_OWNER												'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , CASE WHEN c.ITEM_TYPE IS NULL OR c.ITEM_TYPE = '''' THEN ''-'' ELSE dbo.FN_GET_LOOKUP_CODE_DESC(''ITEM_TYPE_CODE'', c.ITEM_TYPE) END ITEM_TYPE		'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , ISNULL(g.DEPT_NAME_KO, ''-'') DEPT_NAME_KO								'+CHAR(10);
			IF @p_division_id IN ('40')
			BEGIN
				SET @mEXEC = @mEXEC+'			  , ISNULL(c.CELL_TYPE, ''-'') PRODUCT_GROUP								'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(e.ATTRIBUTE5, ''-'') CELL_MODEL									'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , CAST(ISNULL(k.CELL_PACK_COUNT, 0) AS INT) CELL_PACK_COUNT				'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(e.Application, ''-'') APPLICATION								'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.MIN_CAPACITY, ''-'') MIN_CAPACITY								'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(d.SOLDTO_CUSTOMER, ''-'') SOLDTO_CUSTOMER						'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.FORECAST_INFO_SPEC, ''-'') MODEL_SPEC							'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.FORECAST_INFOR_VERSION, ''-'') MODEL_VERSION					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.FORECAST_INFO_ALL, ''-'') SPEC_VERSION							'+CHAR(10);			
			END
			ELSE
			BEGIN
				SET @mEXEC = @mEXEC+'			  , ''-'' PRODUCT_GROUP														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' CELL_MODEL														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , 0 CELL_PACK_COUNT														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' APPLICATION														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' MIN_CAPACITY														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' SOLDTO_CUSTOMER													'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' MODEL_SPEC														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' MODEL_VERSION														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' SPEC_VERSION														'+CHAR(10);	
			END		
			SET @mEXEC = @mEXEC+'	   from (																			'+CHAR(10);

			SET @mEXEC = @mEXEC+'      SELECT																			'+CHAR(10);
			SET @mEXEC = @mEXEC+'      		  key_idx																	'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, division_id																'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, biz_type																	'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, dbo.FN_GET_LOOKUP_CODE_DESC(''BIZ_TYPE'', BIZ_TYPE) AS biz_type_name		'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, project_code																'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, item_id																	'+CHAR(10);
			SET @mEXEC = @mEXEC+'			,(SELECT TOP 1 isnull(NULLIF(NICK_NAME,''''),''-'') FROM DBO.SCM_MST_ITEM_SN x WITH(NOLOCK) WHERE 1=1 AND

 x.ITEM_ID = a.item_id)	nick_name '+CHAR(10);
			SET @mEXEC = @mEXEC+'			,(SELECT TOP 1 isnull(NULLIF(SCP_EXTRA_SPEC,''''),''-'') FROM DBO.SCM_MST_ITEM_SN x WITH(NOLOCK) WHERE 1=1 AND x.DIVISION_ID = a.DIVISION_ID AND x.ITEM_ID = a.item_id)	EXTRA_SPEC '+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, to_site, to_site2																						'+CHAR(10);
			
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'			,(select top 1 SITE_DESCRIPTION from SCM_MST_SITE  where 1=1  and SCM_SITE_ID = TO_SITE2) to_site_name '+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+' 			, to_site as to_site_name							'+CHAR(10);

			SET @mEXEC = @mEXEC+' 			, incoterms																						'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, from_site																						'+CHAR(10);
			SET @mEXEC = @mEXEC+'			,isnull((select top 1 SITE_DESCRIPTION from SCM_MST_SITE  where 1=1  and SCM_SITE_ID = FROM_SITE),''-'') from_site_name '+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, A.bod_id																						'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, A.BOD_FROM_YYYYMMDD																			'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, A.BOD_TO_YYYYMMDD																				'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, ISNULL(transport_mode , ''-'') as transport_mode												'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, ISNULL(lt_day , 0) as lt_day																	'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, origin_from_division_id, origin_to_division_id, electrode_type								'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, cast( round( [dbo].[FN_GET_SCP_ANL_BOH_QTY](division_id ,plan_start_yyyymmdd, plan_type, seq, to_site , item_id,from_yyyymmdd) , 1) as int) as boh '+CHAR(10);
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				BEGIN SET @mEXEC = @mEXEC+' 			, CONVERT(CHAR(10),DATEADD(DAY, (SELECT ISNULL(SHIP_FROZEN, 0) AS SHIP_FROZEN FROM SCM_MST_SITE WHERE DIVISION_ID= division_id AND SCM_SITE_ID=FROM_SITE) , CONVERT(DATE, '''+@p_plan_start_yyyymmdd+''', 112)), 23) AS SHIP_FROZEN '   +CHAR(10); END
			ELSE
				BEGIN SET @mEXEC = @mEXEC+' 			, CONVERT(CHAR(10),DATEADD(DAY, (SELECT ISNULL(SHIP_FROZEN, 0) AS SHIP_FROZEN FROM SCM_MST_SITE WHERE DIVISION_ID= origin_from_division_id AND SCM_SITE_ID=FROM_SITE) , CONVERT(DATE, '''+@p_plan_start_yyyymmdd+''', 112)), 23) AS SHIP_FROZEN '   +CHAR(10); END

			SET @mEXEC = @mEXEC+' 			, measure																						'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, measure_order_no																				'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, measure_label 																				'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, plan_start_yyyymmdd, plan_type, seq, from_yyyymmdd,to_yyyymmdd								'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			'+@mQry_sum
																							 +CHAR(10);
			--2021/10/05 : UI 속도 개선
			--IF(@v_RSLT_FLAG = 'Y')
			--BEGIN
				SET @mEXEC = @mEXEC+'       FROM #TMP_SCP0009_FNL_RSLT_PLAN  a																'+CHAR(10);
			--END
			--ELSE IF(@v_RSLT_FLAG = 'N')
			--BEGIN
			--	SET @mEXEC = @mEXEC+'       FROM #TMP_SCP0009_PLAN  a																		'+CHAR(10);
			--END
			-- BOD 2단계 개발
			--SET @mEXEC = @mEXEC+'	   GROUP BY key_idx, division_id, biz_type, project_code, item_id,to_site,to_site2,incoterms,  from_site,bod_id ,transport_mode, lt_day,origin_from_division_id, origin_to_division_id, electrode_type, measure,measure_order_no,measure_label ,plan_start_yyyymmdd, plan_type, seq,from_yyyymmdd,to_yyyymmdd'+CHAR(10) ;
			SET @mEXEC = @mEXEC+'	   GROUP BY key_idx, division_id, biz_type, project_code, item_id,to_site,to_site2,incoterms,  from_site,bod_id ,transport_mode, lt_day,origin_from_division_id, origin_to_division_id, electrode_type, measure,measure_order_no,measure_label ,plan_start_yyyymmdd, plan_type, seq,from_yyyymmdd,to_yyyymmdd, BOD_FROM_YYYYMMDD, BOD_TO_YYYYMMDD '+CHAR(10) ;


			SET @mEXE

C = @mEXEC+'      ) a																									'+CHAR(10);
			SET @mEXEC = @mEXEC+'      LEFT OUTER JOIN W_ENERGY	 EG  on a.ITEM_ID	= EG.ITEM_ID AND A.DIVISION_ID = '''+@DIV_ENERGY+''' 	'+CHAR(10); -- 20230411 ENERGY / only div = 82 ess
			SET @mEXEC = @mEXEC+'      LEFT OUTER JOIN (SELECT DIVISION_ID																	'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , PROJECT_CODE																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , PROJECT_NAME																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , PROJECT_OWNER																	'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, PROJECT_CODE ORDER BY PROJECT_VER_SEQ ASC ) NUMS											'+CHAR(10);
			SET @mEXEC = @mEXEC+'					FROM SCM_MST_PROJECT WITH(NOLOCK)														'+CHAR(10);
			SET @mEXEC = @mEXEC+'				 ) b  on a.PROJECT_CODE	= b.PROJECT_CODE 				'+CHAR(10);

			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				  AND a.DIVISION_ID	= b.DIVISION_ID 				'+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+'				  AND a.origin_to_division_id = b.DIVISION_ID 				'+CHAR(10);

			SET @mEXEC = @mEXEC+'					 and b.NUMS=1																			'+CHAR(10);
			SET @mEXEC = @mEXEC+'      LEFT JOIN (SELECT c1.DIVISION_ID																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.ITEM_ID																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.ITEM_NAME																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.NICK_NAME																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.ITEM_TYPE																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c2.SEGMENT2 CELL_TYPE															'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , ROW_NUMBER() OVER ( PARTITION BY c1.DIVISION_ID, c1.ITEM_ID ORDER BY  CASE c1.ITEM_TYPE WHEN ''P'' THEN 999 WHEN ''H'' THEN 888 WHEN ''R'' THEN 777  WHEN ''Q'' THEN 666 ELSE 0 END  DESC ) NUMS																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'					FROM SCM_MST_ITEM_SN c1 WITH(NOLOCK)													'+CHAR(10);
			SET @mEXEC = @mEXEC+'					LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL c2 WITH(NOLOCK)									'+CHAR(10);
			SET @mEXEC = @mEXEC+'					 ON c1.CELL_TYPE = c2.SEGMENT1 															'+CHAR(10);
			SET @mEXEC = @mEXEC+'					 AND c2.LOOKUP_TYPE = ''CELL_TYPE'' 													'+CHAR(10);
			SET @mEXEC = @mEXEC+'				 ) c  on a.item_id=c.item_id																'+CHAR(10);

			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				     and a.division_id=c.division_id																'+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+'				     and a.origin_to_division_id=c.division_id																'+CHAR(10);
			SET @mEXEC = @mEXEC+'				     and c.nums=1																			'+CHAR(10);
			
			/*add start jahn1501*/
			IF @p_division_id IN ('40')
			BEGIN
				SET @mEXEC = @mEXEC+'      LEFT JOIN (SELECT DIVISION_ID																		'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , ITEM_ID																			'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_CELL_MODEL CELL_MODEL												'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_CELL_PACK_COUNT CELL_PACK_COUNT									'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , MIN_CAPACITY																		'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_SPEC																'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFOR_VERSION															'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_SPEC + FORECAST_INFOR_VERSION AS FORECAST_INFO_ALL					'+CHAR(10);
				SET @mEXEC = @mEXEC+'					FROM DM_MST_ITEM_SINGLE_V WITH(NOLOCK)													'+CHAR(10);
				SET @mEXEC = @mEXEC+'				 ) k  on a.item_id=k.item_id																'+CHAR(10);
				SET @mEXEC = @mEXEC+'				     and a.division_id=k.division_id														'+CHAR(10);
			END

			/*end*/		
			/********** DEPT NAME START **********/
			SET @mEXEC = @mEXEC+'			LEFT JOIN SCM_MST_SITE d 					'+CHAR(10);
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
			BEGIN
				SET @mEXEC = @mEXEC+'			   ON d.division_id	= a.division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  AND d.SCM_SITE_ID	= a.TO_SITE 					'+CHAR(10);
			END
			ELSE
			BEGIN
				SET @mEXEC = @mEXEC+'			   on d.division_id	= a.origin_to_division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  and d.scm_site_id	= a.TO_SITE2					'+CHAR(10);
			END
			SET @mEXEC = @mEXEC+'				  AND d.VALID_YN       = ''Y'' 					'+CHAR(10);


			SET @mEXEC = @mEXEC+'			LEFT JOIN SCM_MST_SITE_ITEM e 					'+CHAR(10);
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
			BEGIN
				SET @mEXEC = @mEXEC+'			    on e.division_id	= a.division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			    and e.scm_site_id	= a.TO_SITE					'+CHAR(10);
			END
			ELSE
			BEGIN
				SET @mEXEC = @mEXEC+'			    on e.division_id	= a.origin_to_division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			    and e.scm_site_id	= a.TO_SITE2					'+CHAR(10);
			END
			SET @mEXEC = @mEXEC+'					and e.project_code	= a.project_code 					'+CHAR(10);
			SET @mEXEC = @mEXEC+'					and e.item_id		= a.item_id 					'+CHAR(10);
			SET @mEXEC = @mEXEC+'					and e.VALID_YN		=''Y'' 					'+CHAR(10);

			SET @mEXEC = @mEXEC+'			LEFT JOIN [dbo].[SCM_MST_SSO_USER_INFO] f WITH(NOLOCK) 					'+CHAR(10);
			SET @mEXEC = @mEXEC+'				   ON  substring( e.OWNER, 0, case when charindex('','',e.OWNER) = 0 then len(e.OWNER)+1 else charindex('','',e.OWNER) end ) = f.USER_ID 					'+CHAR(10);
			
            -- 20241113 E20241105-000454 : 소형외 사업부도 소형과 동일하게 Site 의 부서 대신 Site Itme의 Owner 부서 기준으로 표시
			SET @mEXEC = @mEXEC+'			LEFT JOIN [dbo].[SCM_MST_SSO_DEPT_INFO] g WITH(NOLOCK) 					'+CHAR(10);

			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				   ON  f.DEPT_ID = g.DEPT_ID 					'+CHAR(10);
			ELSE 
				SET @mEXEC = @mEXEC+'				   ON  f.DEPT_ID = g.DEPT_ID 					'+CHAR(10);

		 /*
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				   ON  CASE WHEN a.DIVISION_ID = ''40'' THEN f.DEPT_ID ELSE d.DEPT_ID END  = g.DEPT_ID 					'+CHAR(10);
			ELSE 
				SET @mEXEC = @mEXEC+'				   ON  CASE WHEN a.origin_to_division_id = ''40'' THEN f.DEPT_ID ELSE d.DEPT_ID END  = g.DEPT_ID 					'+CHAR(10);
           */
	        IF NOT(@p_team_id  IS NULL   OR  @p_team_id = '') 
			BEGIN 
			    SET @mEXEC = @mEXEC+ ' WHERE 1=1 					'+CHAR(10);
			    SET @mEXEC = @mEXEC+ [dbo].[FN_SCM_GET_WHERE_SQL]('g.DEPT_ID', 'IN', @p_team_id) +CHAR(10);
			END;
			
			SET @mEXEC = @mEXEC+'      ORDER BY a.division_id, a.biz_type, a.item_id, a.to_site, project_code, a.incoterms, a.from_site, a.bod_id, a.measure_order_no		'+CHAR(10);


			SET @mEXEC = @mEXEC+' OPTION (HASH GROUP) ; '+CHAR(10);


			---------------------------------------------------------
			--DEBUG QRY 출력
			---------------------------------------------------------
			IF( @debug_mode ='T')
			BEGIN
				DECLARE @POS INT =1;
				SET @POS =1;
				DECLARE @LEN INT =LEN(@mEXEC);
				WHILE @POS <= @LEN
				BEGIN
					PRINT SUBSTRING(@mEXEC,@POS,4000);
					SET @POS = @POS+4000;
				END;
			END;
			---------------------------------------------------------

			EXEC (@mEXEC);
		END;


		PRINT '10. Pivot End '+CONVERT(CHAR(23), GETDATE(), 21);


		--################################################################################################
		-- Return Data 2 - IsEditable, plan_Start_Date
		--#########################################################################

@mEXEC+'		dbo.FN_GET_LOOKUP_CODE_DESC(''BIZ_TYPE'', a.OPERATION_GROUP) as OPERATION_GROUP ,		'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		ISNULL(NULLIF(a.ELECTRODE_TYPE,''''), ''-'') AS ELECTRODE_TYPE ,									'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		a.REQUIRED_QTY ,																		'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		a.PLANNED_QTY ,																			'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		a.PROBLEM_TYPE AS PROBLEM_TYPE ,														'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		a.LPST ,																				'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		a.STOCK_PLAN_LOT_ID																		'+CHAR(10);
	--SET @mEXEC = @mEXEC+'	FROM SCP_ANL_PROBLEM_REPORT_PEGGING (nolock) a												'+CHAR(10);
	--SET @mEXEC = @mEXEC+'	LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL (nolock) b on b.lookup_type=''PEGGING_OPERATION''	'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.pegging_operation_code = b.SEGMENT1												'+CHAR(10);
	--SET @mEXEC = @mEXEC+'	WHERE a.DIVISION_ID = ''' + @p_division_id + '''											'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.PLAN_START_YYYYMMDD = ''' + @p_Plan_Start_yyyymmdd + '''										'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.PLAN_TYPE = ''' + @p_PLAN_TYPE + '''															'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.SEQ = ' + @v_SEQ + '																		'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.PEGGING_OPERATION_CODE in (''ALLOC'',''PSHIP'',''CSHIP'',''ESHIP'')				'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.OPERATION_GROUP = ''' + @p_biz_type + '''														'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.TO_SITE = ''' + @p_to_site + '''															'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.ITEM_ID = ''' + @p_item_id + '''																'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and a.DUE_DATE = CONVERT(DATETIME , '''+ @p_duedate + ''')											'+CHAR(10);
	--SET @mEXEC = @mEXEC+'		and dbo.fn_scm_split(a.[eng_demand_id],2,''::'') = ''' + @p_project_code + '''						'+CHAR(10);

	--IF @p_division_id = 'EE'
	--BEGIN
	--	--SET @mEXEC = @mEXEC+'		AND A.ORIGIN_TO_DIVISION_ID = ''' + @p_origin_to_division_id + '''								'+CHAR(10);

	--	--IF NOT(@p_electrode_type = '' OR @p_electrode_type IS NULL OR @p_electrode_type = '-')
	--	--	SET @mEXEC = @mEXEC+'		AND A.ORIGIN_FROM_DIVISION_ID = ''' + @p_origin_from_division_id + '''							'+CHAR(10);

	--	IF NOT(@p_electrode_type = '' OR @p_electrode_type IS NULL OR @p_electrode_type = '-')
	--		SET @mEXEC = @mEXEC+'		AND A.ELECTRODE_TYPE = ''' + @p_electrode_type + '''												'+CHAR(10);
	--END;

	--EXEC (@mEXEC);

	--DECLARE @POS INT =1;
	--	DECLARE @LEN INT =LEN(@mEXEC);
	--	WHILE @POS <= @LEN
	--	BEGIN
	--		PRINT SUBSTRING(@mEXEC,@POS,4000);
	--		SET @POS = @POS+4000;
	--	END;

END

	VALUES (ERROR_PROCEDURE()
				   ,'ERROR'
				   ,NULL
				   ,ERROR_MESSAGE()
				   ,NULL
				   ,SYSDATETIME()
				   ,SYSDATETIME()
				   ,ERROR_PROCEDURE()
				   ,SYSDATETIME()
				   ,ERROR_PROCEDURE());

			IF @@TRANCOUNT > 0
			  COMMIT WORK;
		  END;

		  -- error코드, errror 메시지 반환
		  SELECT 'F' AS result_code, '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE() AS ERR_MESSAGE ;
		  --SELECT '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE();
		END CATCH;
	END

/*
 * Program ID   : SCP0009_GET_SHIPMENT_PLAN_FG_RTF_WEEKLY
 * Description  : Shipment Plan 조회
 * Program History
 
 *===================================================================================================
 *   Date       In Charge		        Description
 *===================================================================================================
 * 2022/11/11   chaan       	V1.0.0  Initial Release
 * 2023.01.02   lwy             PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - 조회기준 변경(main / hist) - 당주,전주(main) / 당주,전주 이전(hist) 
 * 2023.04.10   LWY				PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - DIVISION_ID 공통화 작업(div_commonization)
 * 2024.06.27   ksg             E20240612-001030 Shipment plan FG 실적조회 시 confirm_id 참조하는 데이터 변경 (from_site, item_id →from_site only)
 *                                           선적계획 실적구간 조회 시 confirm_id 를 [SSP_ANL_SHIP_CONFIRM]에 조인하여 from_site_ID와 item_id 를 업데이트해서 적용하는데,
 *                                           조인해서 가져오는 값을 from_site_id 만 가져오고, item_id 는 기존에 있는 값을 사용하여 출하실적으로 적용
 */

--CREATE PROCEDURE [dbo].[SCP0009_GET_SHIPMENT_PLAN_FG_RTF_WEEKLY]
CREATE PROCEDURE [dbo].[SCP0009_GET_SHIPMENT_PLAN_FG_RTF_WEEKLY]
      @p_is_plan				NVARCHAR(1)			= N'T'
    , @p_division_id			NVARCHAR(30)
    , @p_from_yyyymmdd		    NVARCHAR(8)
    , @p_to_yyyymmdd			NVARCHAR(8)
    , @p_program_id			    NVARCHAR(10)        = 'SCP0009'
    , @p_sheet_name			    NVARCHAR(30)        = 'Shipment Plan FG'
    , @p_user_id				NVARCHAR(30)
    , @debug_mode               NVARCHAR(1)         ='F'
AS
BEGIN
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SET NOCOUNT ON; 

	--DECLARE @p_is_plan				NVARCHAR(1)			= N'T';
	--DECLARE @p_division_id			NVARCHAR(30)		= N'40';
	--DECLARE @p_from_yyyymmdd		NVARCHAR(8)			= N'20221017';
	--DECLARE @p_to_yyyymmdd			NVARCHAR(8)			= N'20221023';
	--DECLARE @p_program_id			NVARCHAR(10)		= 'SCP0009';
	--DECLARE @p_sheet_name			NVARCHAR(30)		= 'Shipment Plan FG';
	--DECLARE @p_user_id				NVARCHAR(30)		= N'iamarock';
	--DECLARE @debug_mode             NVARCHAR(1)			='F';



	DECLARE @p_biz_type				NVARCHAR(30)		= N'P';

	DECLARE @p_plan_start_yyyymmdd  NVARCHAR(8)			= N'';
	DECLARE @p_seq					NVARCHAR(10)		= N'';
	DECLARE @p_plan_type			NVARCHAR(10)		= IIF(@p_is_plan = 'T', 'FN', 'PR');
	DECLARE @p_year       			NVARCHAR(4)		    = SUBSTRING(@p_from_yyyymmdd, 1, 4);
	DECLARE @V_PRE_YYYYMM           NVARCHAR(6)			= N'';
	DECLARE @V_POST_YYYYMM          NVARCHAR(8)			= N'';
	DECLARE @V_THIS_MONDAY          NVARCHAR(8)			= N'';
	DECLARE @V_LAST_SUNDAY          NVARCHAR(8)			= N'';
	DECLARE @V_PRE_FROM_YYYYMMDD    NVARCHAR(8)			= N'';


    IF OBJECT_ID (N'tempdb..#T_SCP0009_TERMS', N'U') IS NOT NULL 
		DROP TABLE #T_SCP0009_TERMS

	--CREATE TABLE #T_SCP0009_TERMS
 --   (
 --         ISO_YYYYWW                    NVARCHAR(6)
 --       , THIS_ISO_YYYYWW               NVARCHAR(6)
 --       , THIS_FROM_YYYYMMDD            NVARCHAR(8)
 --       , THIS_TO_YYYYMMDD              NVARCHAR(8)
 --       , PRE_ISO_YYYYWW                NVARCHAR(6)
 --       , PRE_FROM_YYYYMMDD             NVARCHAR(8)
 --       , PRE_TO_YYYYMMDD               NVARCHAR(8)
 --       , POST_ISO_YYYYWW               NVARCHAR(6)
 --       , POST_FROM_YYYYMMDD            NVARCHAR(8)
 --       , POST_TO_YYYYMMDD              NVARCHAR(8)
 --       , DM_RTF_YN                     NVARCHAR(1)
 --       , FG_SEQ_P                      BIGINT
 --       , FG_SEQ_R                      BIGINT
 --       , WHOLE_FROM_YYYYMMDD           NVARCHAR(8)
 --       , WHOLE_TO_YYYYMMDD             NVARCHAR(8)
 --       , WHOLE_PRE_FROM_YYYYMMDD       NVARCHAR(8)
 --       , WHOLE_THIS_MONDAY             NVARCHAR(8)
 --       , WHOLE_LAST_SUNDAY             NVARCHAR(8)
 --       , WHOLE_PRE_YYYYMM              NVARCHAR(6)
 --       , WHOLE_POST_YYYYMM             NVARCHAR(6)
 --   )
 BEGIN--SCP0092_GET_RTF_ARCHEIVEMENT_RATE_TERM

begin------------------------------------------------------------------------
      --INSERT INTO EXEC 중복으로 호출불가하여 SCP0092_GET_RTF_ARCHEIVEMENT_RATE_TERM 내용을 그대로 이곳으로 복사함

   --DECLARE @p_division_id              NVARCHAR(30)       = N'40';  
   --DECLARE @p_year                     NVARCHAR(4)        = N'2022';


   DECLARE @V_WHOLE_FROM_YYYYMMDD            NVARCHAR(8)        = N'';
   DECLARE @V_WHOLE_TO_YYYYMMDD              NVARCHAR(8)        = N'';
   DECLARE @V_WHOLE_PRE_YYYYMM               NVARCHAR(6)        = N'';
   DECLARE @V_WHOLE_POST_YYYYMM              NVARCHAR(6)        = N'';
   DECLARE @V_WHOLE_THIS_MONDAY              NVARCHAR(8)        = N'';
   DECLARE @V_WHOLE_NEXT_MONDAY              NVARCHAR(8)        = N'';
   DECLARE @V_WHOLE_LAST_SUNDAY              NVARCHAR(8)        = N'';
   DECLARE @V_WHOLE_NEXT_SUNDAY              NVARCHAR(8)        = N'';
   DECLARE @V_WHOLE_PRE_FROM_YYYYMMDD        NVARCHAR(8)        = N'';

    SET @V_WHOLE_FROM_YYYYMMDD            = '';
    SET @V_WHOLE_TO_YYYYMMDD              = '';
    SET @V_WHOLE_PRE_YYYYMM               = @p_year + '01';
    SET @V_WHOLE_POST_YYYYMM              = @p_year + '12';

    
    SELECT    @V_WHOLE_FROM_YYYYMMDD  = MIN(C.BASIS_START_DATE)
            , @V_WHOLE_TO_YYYYMMDD    = MAX(C.BASIS_END_DATE)
    FROM    SCM_SYS_CALENDAR_M C
    WHERE   1=1
            AND SUBSTRING(C.ISO_YYYYWW, 1, 4) = @p_year;

    SET @V_WHOLE_THIS_MONDAY     = CONVERT(CHAR(8), DATEADD(DD, -7, dbo.FN_NEXT_DAY( GETDATE(), 'MON')), 112);
    SET @V_WHOLE_NEXT_MONDAY     = CONVERT(CHAR(8), DATEADD(DD,  1, dbo.FN_NEXT_DAY( GETDATE(), 'MON')), 112);
    SET @V_WHOLE_LAST_SUNDAY     = CONVERT(CHAR(8), DATEADD(DD, -7, dbo.FN_NEXT_DAY( GETDATE(), 'SUN')), 112);
    SET @V_WHOLE_NEXT_SUNDAY     = CONVERT(CHAR(8), DATEADD(DD,  7, dbo.FN_NEXT_DAY( GETDATE(), 'SUN')), 112);--Pack FG 실적때문에 차주까지 조회

--Pack FG 실적때문에 차주까지 조회    SET @V_WHOLE_TO_YYYYMMDD    = IIF(@V_WHOLE_TO_YYYYMMDD >= @V_WHOLE_THIS_MONDAY, @V_WHOLE_LAST_SUNDAY, @V_WHOLE_TO_YYYYMMDD); -- 기간이 올해까지이더라도 전주까지만 조회
    SET @V_WHOLE_TO_YYYYMMDD    = IIF(@V_WHOLE_TO_YYYYMMDD >= @V_WHOLE_THIS_MONDAY, @V_WHOLE_NEXT_SUNDAY, @V_WHOLE_TO_YYYYMMDD); -- 기간이 올해까지이더라도 전주까지만 조회



--set @V_WHOLE_FROM_YYYYMMDD    = N'20220110'; --test
--set @V_WHOLE_TO_YYYYMMDD      = N'20220116'; --test

--    SET @V_WHOLE_PRE_FROM_YYYYMMDD                 = CONVERT(CHAR(8), DATEADD(DD, -14, dbo.FN_NEXT_DAY(@V_WHOLE_FROM_YYYYMMDD, 'MON')), 112); -- RTF 를위해 지정한 기간 전주까지 기간에 포함
    SET @V_WHOLE_PRE_FROM_YYYYMMDD                 = CONVERT(CHAR(8), DATEADD(DD, -21, dbo.FN_NEXT_DAY(@V_WHOLE_FROM_YYYYMMDD, 'MON')), 112); -- RTF 를위해 지정한 기간 전주까지 기간에 포함
--print @V_WHOLE_PRE_FROM_YYYYMMDD;return;


    IF OBJECT_ID (N'tempdb..#T_WEEKS_ALL', N'U') IS NOT NULL
		DROP TABLE #T_WEEKS_ALL

    CREATE TABLE #T_WEEKS_ALL
    (
          ISO_YYYYWW                    NVARCHAR(6)
        , THIS_ISO_YYYYWW               NVARCHAR(6)
        , THIS_FROM_YYYYMMDD            NVARCHAR(8)
        , THIS_TO_YYYYMMDD              NVARCHAR(8)
        , PRE_ISO_YYYYWW                NVARCHAR(6)
        , PRE_FROM_YYYYMMDD             NVARCHAR(8)
        , PRE_TO_YYYYMMDD               NVARCHAR(8)
        , POST_ISO_YYYYWW               NVARCHAR(6)
        , POST_FROM_YYYYMMDD            NVARCHAR(8)
        , POST_TO_YYYYMMDD              NVARCHAR(8)
        , DM_RTF_YN                     NVARCHAR(1)
        , FG_SEQ_P                      BIGINT
        , FG_SEQ_R                      BIGINT
        , WHOLE_FROM_YYYYMMDD           NVARCHAR(8)
        , WHOLE_TO_YYYYMMDD             NVARCHAR(8)
        , WHOLE_PRE_FROM_YYYYMMDD       NVARCHAR(8)
        , WHOLE_THIS_MONDAY             NVARCHAR(8)
        , WHOLE_LAST_SUNDAY             NVARCHAR(8)
        , WHOLE_PRE_YYYYMM              NVARCHAR(6)
        , WHOLE_POST_YYYYMM             NVARCHAR(6)
    );

    DECLARE @V_CURR_ISO_YYYYWW

      , @V_NEXT_MONDAY            = POST_FROM_YYYYMMDD
            , @p_seq                    = IIF(@p_is_plan = 'T', FG_SEQ_P, FG_SEQ_R)
    FROM    #T_SCP0009_TERMS
    WHERE   THIS_FROM_YYYYMMDD = @p_from_yyyymmdd


	declare @v_data_cnt nvarchar(8);
	set @v_data_cnt =0;

	DECLARE @v_cnt_usr_measure	nvarchar =0;
	DECLARE @v_from_yyyymmdd     AS NVARCHAR(8);
	DECLARE @v_to_yyyymmdd       AS NVARCHAR(8);
	DECLARE @v_from_result       AS NVARCHAR(8);
	DECLARE @v_to_result         AS NVARCHAR(8);
	DECLARE @v_min_yyyymmdd      AS NVARCHAR(8);   -- 2021/07/21	
	DECLARE @v_RSLT_FLAG AS NVARCHAR(1) = 'Y';   -- 2021/07/21

	SET @v_cnt_usr_measure = (
								SELECT COUNT(*)
								FROM scm_mst_titleset_user
								WHERE 1=1
								 AND program_id  =  @p_program_id
								 AND sheet_name  =  @p_sheet_name
								 AND user_id     =  @p_user_id
							  )    

	SET @v_from_yyyymmdd = '';
	SET @v_to_yyyymmdd   = '';
	SET @v_from_result   = '';
	SET @v_to_result     = '';

	  SELECT @v_from_yyyymmdd = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_plan_start_yyyymmdd

	  SELECT @v_from_result = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_from_yyyymmdd;

	  SELECT @v_to_result = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_to_yyyymmdd;

	  IF @v_from_yyyymmdd > @v_from_result
		  BEGIN -- 실적 보여줌		  
		  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
		  SET @v_to_result     = @v_from_yyyymmdd;
		  END;
	  ELSE IF @v_from_yyyymmdd <= @v_from_result
		  BEGIN -- 실적 없음
		  
		  SET @v_RSLT_FLAG = 'N';  -- 2021/07/21 // 계획만 조회
		  
		  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
		  SET @v_from_result = CONVERT(CHAR(8), DATEADD(MM, 6, convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_to_result = CONVERT(CHAR(8), DATEADD(MM, -6, convert(datetime,@p_plan_start_yyyymmdd)), 112)
		  END;
	  ELSE IF @v_from_yyyymmdd > @v_to_result
		  BEGIN
		  SET @v_from_yyyymmdd = CONVERT(CHAR(8), DATEADD(MM, -6,  convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_to_yyyymmdd = CONVERT(CHAR(8), DATEADD(MM, -6,  convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_from_result = @p_from_yyyymmdd;
		  SET @v_to_result = @p_to_yyyymmdd;
		  END;
	  ELSE IF @v_from_yyyymmdd = @v_to_result
		  BEGIN
		  SET @v_to_yyyymmdd = @v_from_yyyymmdd
		  SET @v_from_result = @p_from_yyyymmdd;
		  SET @v_to_result = @p_to_yyyymmdd;
		  END;

print '@p_division_id : ' + @p_division_id;
print '@p_biz_type : ' + @p_biz_type;
print '@p_plan_type : ' + @p_plan_type;
print '@p_seq : ' + @p_seq;
print '@p_plan_start_yyyymmdd : ' + @p_plan_start_yyyymmdd;
PRINT '@v_from_yyyymmdd : ' + @v_from_yyyymmdd;
PRINT '@v_to_yyyymmdd : ' + @v_to_yyyymmdd;
PRINT '@v_from_result : ' + @v_from_result;
PRINT '@v_to_result : ' + @v_to_result	;
--return;

	DECLARE @mEXEC NVARCHAR(MAX);

	-- 2021.11.24 : 체크 시 bucket='daily' 조회

	/********************************************************************************
	* 임시테이블만들기 - Header 부분
	********************************************************************************/

	-- ##############################################################################
	-- MEASURE 정보 생성
	-- ##############################################################################
	IF OBJECT_ID('tempdb..#TMP_SCP0009_MEASURE') IS NOT NULL
		DROP TABLE #TMP_SCP0009_MEASURE
	
	SELECT M.COLUMN_NAME
		 , M.COLUMN_LABEL_NAME
		 , ISNULL(T.SORT_ORDER_NO, M.SORT_ORDER_NO ) MEASURE_ORDER_NO
	  INTO #TMP_SCP0009_MEASURE
	  FROM SCM_MST_SHEET_MEASURE M
      LEFT JOIN ( SELECT *
				    FROM SCM_MST_TITLESET_USER
				   WHERE PROGRAM_ID = @p_program_id
					 AND SHEET_NAME	= @p_sheet_name
					 AND USER_ID	= @p_user_id
				) T
		ON M.PROGRAM_ID		= T.PROGRAM_ID
	   AND M.SHEET_NA

RODE_TYPE		= @p_electrode_type
					AND ISNULL(NULLIF(ELECTRODE_TYPE,''),'-') = ISNULL(NULLIF(@p_electrode_type,''),'-')
				;
				
				EXEC [PR_SCP_ANL_SHIPMENT_PLAN_FG_FIX_HIST]
					 @v_fix_id
					,@p_division_id
					,@p_biz_type
					,@p_item_id
					,@p_to_site
					,@p_from_site
					,@p_project_code
					,@p_incoterms
					,@p_bod_id
					,@p_yyyymmdd
					,@nQty
					,@p_origin_from_division_id
					,@p_origin_to_division_id
					,@p_electrode_type
					,@v_fix_reason
					,@p_last_updated_by
					,@d_event_date
					,@p_last_updated_by
				;

			END

			--이력저장
			EXEC [dbo].[PR_SCP_ANL_SHIPMENT_PLAN_FG_HIST]
				@p_division_id  		,
				@p_plan_start_yyyymmdd	,
				@p_plan_type			,
				@p_seq					,
				@p_biz_type				,
				@p_project_code			,
				@p_item_id				,
				@p_to_site				,
				@p_incoterms			,
				@p_from_site			,
				@p_bod_id				,
				@p_measure				,
				@p_yyyymmdd				,
				@nQty					,
				@p_origin_from_division_id	,
				@p_origin_to_division_id	,
				@p_electrode_type		,
				@p_created_by			,
				@p_last_updated_by
			;
			
			commit;
		END

		SET @v_log_type = 'END';
		SET @v_log_message = '########## END of procedure ##########';
		SET @v_description = '';
		SET @d_event_date = SYSDATETIME();
		IF @p_last_row = 'Y'
		BEGIN
			EXEC PR_SCM_SYS_LOG_BATCH_CALL_TRAN @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
		END
		
		-- 결과코드, 결과 카운트 반환
		SELECT  'S' AS result_code,  @mst_loop_cnt AS result_cnt ;

	END TRY

	BEGIN CATCH 
		BEGIN
			if (xact_state() <> 0) ROLLBACK TRAN; --입력 데이타 롤백 처리
						
			INSERT INTO scm_sys_log_batch (program_name,log_type,log_count,log_message,description,event_date,creation_date,created_by,last_update_date,last_updated_by)
			VALUES (ERROR_PROCEDURE(),'ERROR',NULL,ERROR_MESSAGE(),NULL,SYSDATETIME(),SYSDATETIME(),ERROR_PROCEDURE(),SYSDATETIME(),ERROR_PROCEDURE());

			--IF @@TRANCOUNT > 0
			--  COMMIT WORK;

			-- error코드, errror 메시지 반환
			SELECT 'F' AS result_code , 0 as result_cnt ;

			IF( @v_err_code IS NULL OR @v_err_code ='')
				SET @v_err_code= ERROR_NUMBER() ;
			IF( @v_err_message IS NULL OR @v_err_message ='') 
				SET @v_err_message=  ERROR_MESSAGE();
			   						
			/* 에러 메시지, 에러 데이터  반환   */
			SELECT  @v_err_code			AS err_code
				   ,@v_err_message		AS err_message
				   ,@p_division_id		AS DIVISION_ID  
				   ,@p_biz_type			as BIZ_TYPE
				   ,@p_project_code		as PROJECT_CODE
				   ,@p_item_id			AS ITEM_ID
				   ,@p_to_site			AS TO_SITE
				   ,@p_incoterms		AS INCOTERMS
				   ,@p_from_site		AS FROM_SITE
				   ,@p_bod_id			AS BOD_ID
				   ,@p_measure			AS MEASURE
				   ,@p_yyyymmdd			AS YYYYMMDD
				   ,@p_qty				as qty
				   , error_line()
			; 

		END;
	END CATCH;
END

			FROM SCP_ANL_SHIPMENT_PLAN_FIX A, #TblDynamic_SCP0009 B
			WHERE A.division_id				= B.p_division_id
			and A.BIZ_TYPE					= B.p_biz_type
			and A.ITEM_ID					= B.p_item_id
			and A.TO_SITE					= B.p_to_site
			and A.FROM_SITE					= B.p_from_site
			and A.PROJECT_CODE				= B.p_project_code
			and A.INCOTERMS					= B.p_incoterms
			and A.BOD_ID					= B.p_bod_id
			and A.yyyymmdd					= B.p_yyyymmdd
			AND A.ORIGIN_FROM_DIVISION_ID	= B.p_origin_from_division_id
			AND A.ORIGIN_TO_DIVISION_ID		= B.p_origin_to_division_id
			AND ISNULL(NULLIF(A.ELECTRODE_TYPE,''),'-') = ISNULL(NULLIF(B.p_electrode_type,''),'-')

			-- 5. FIX이력저장
			EXEC [dbo].[PR_SCP_ANL_SHIPMENT_PLAN_FG_FIX_HIST_DATASET] @SCP0009
			
			-- 6. 이력저장
			EXEC [dbo].[PR_SCP_ANL_SHIPMENT_PLAN_FG_HIST_DATASET] @SCP0009

			commit;

		END

		SET @v_exec_time  =  REPLICATE('0', 2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) + ':' +     
							 REPLICATE('0', 2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60)) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60))    

		SET @v_log_type = 'END';
		SET @v_log_message = '########## END of procedure ##########';
		SET @v_description  = N'[' + @v_exec_time + ']';   
		SET @d_event_date = SYSDATETIME();

		EXEC PR_SCM_SYS_LOG_BATCH_CALL_TRAN @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
		
		-- 결과코드, 결과 카운트 반환
		SELECT  'S' AS result_code,  @max_loop_cnt AS result_cnt ;

	END TRY

	BEGIN CATCH 
		BEGIN
			if (xact_state() <> 0) ROLLBACK TRAN; --입력 데이타 롤백 처리
						
			INSERT INTO scm_sys_log_batch (program_name,log_type,log_count,log_message,description,event_date,creation_date,created_by,last_update_date,last_updated_by)
			VALUES (ERROR_PROCEDURE(),'ERROR',NULL,ERROR_MESSAGE(),NULL,SYSDATETIME(),SYSDATETIME(),ERROR_PROCEDURE(),SYSDATETIME(),ERROR_PROCEDURE());

			--IF @@TRANCOUNT > 0
			--  COMMIT WORK;

			-- error코드, errror 메시지 반환
			--SELECT 'F' AS result_code , 0 as result_cnt ;
			/*
			IF( @v_err_code IS NULL OR @v_err_code ='')
				SET @v_err_code= ERROR_NUMBER() ;
			IF( @v_err_message IS NULL OR @v_err_message ='') 
				SET @v_err_message=  ERROR_MESSAGE();
			*/
			   						
			/* 에러 메시지, 에러 데이터  반환   */
			/*
			SELECT  @v_err_code			AS err_code
				   ,@v_err_message		AS err_message
				   , error_line()
			; 
			*/

			-- error코드, errror 메시지 반환
			SELECT 'F' AS result_code, '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE() AS err_message ;

		END;
	END CATCH;

	IF OBJECT_ID('tempdb..#TblDynamic_SCP0009') IS NOT NULL	
		DROP TABLE #TblDynamic_SCP0009 

END

/*
 * Program ID   : SCP0009_SAVE_ANL_SHIPMENT_PLAN_FG_FIX
 * Description  : SHIPMENT PLAN FG FIX 등록,수정
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2018/05/24   KYH				Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018/07/19	KYH				신규 컬럼 추가 조회. (ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, ELECTRODE_TYPE) 
 */
CREATE PROCEDURE [dbo].[SCP0009_SAVE_ANL_SHIPMENT_PLAN_FG_FIX]
	 @p_active_flag			NVARCHAR(MAX)
	,@p_division_id			NVARCHAR(MAX)
	,@p_biz_type			NVARCHAR(MAX)
	,@p_item_id 			NVARCHAR(MAX)
	,@p_to_site 			NVARCHAR(MAX)
	,@p_from_site			NVARCHAR(MAX)
	,@p_project_code		NVARCHAR(MAX)
	,@p_incoterms			NVARCHAR(MAX)
	,@p_bod_id				NVARCHAR(MAX)
	,@p_yyyymmdd			NVARCHAR(MAX)
	,@p_qty					NVARCHAR(MAX)
	,@p_origin_from_division_id		NVARCHAR(MAX)
	,@p_origin_to_division_id		NVARCHAR(MAX)
	,@p_electrode_type		NVARCHAR(MAX)
	,@p_fix_reason			NVARCHAR(MAX)
	,@p_user_id  			NVARCHAR(50)
	,@debug_mode            NVARCHAR(1)='F'
AS

BEGIN

	SET NOCOUNT ON;

	--SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

	DECLARE @recv_active_flag		NVARCHAR(MAX);
	SET @recv_active_flag = NULL;		
	SET @recv_active_flag = @p_active_flag;

	DECLARE @v_active_flag		NVARCHAR(MAX);
	DECLARE @v_division_id		NVARCHAR(MAX);
	DECLARE @v_biz_type			NVARCHAR(MAX);
	DECLARE @v_item_id 			NVARCHAR(MAX);	
	DECLARE @v_to_site 			NVARCHAR(MAX);
	DECLARE @v_from_site		NVARCHAR(MAX);
	DECLARE @v_project_code		NVARCHAR(MAX);
	DECLARE @v_incoterms		NVARCHAR(MAX);
	DECLARE @v_bod_id			NVARCHAR(MAX);
	DECLARE @v_yyyymmdd			NVARCHAR(MAX);
	DECLARE @v_qty				NVARCHAR(MAX);
	DECLARE @v_origin_from_division_id		NVARCHAR(MAX);
	DECLARE @v_origin_to_division_id		NVARCHAR(MAX);
	DECLARE @v_electrode_type	NVARCHAR(MAX);
	DECLARE @v_fix_reason		NVARCHAR(MAX);
	DECLARE @v_last_updated_by	NVARCHAR(MAX);
	DECLARE @v_fix_id 			NVARCHAR(MAX);

	SET @v_active_flag = NULL;
	SET @v_division_id = NULL;
	SET @v_biz_type = NULL;
	SET @v_item_id = NULL;
	SET @v_to_site = NULL;
	SET @v_from_site = NULL;
	SET @v_project_code = NULL;
	SET @v_incoterms = NULL;
	SET @v_bod_id = NULL;
	SET @v_yyyymmdd = NULL;	 
	SET @v_qty = NULL;
	SET @v_origin_from_division_id = NULL;
	SET @v_origin_to_division_id = NULL;
	SET @v_electrode_type = NULL;
	SET @v_fix_reason = NULL;
	SET @v_last_updated_by = @p_user_id;
	SET @v_fix_id = null;

	DECLARE @v_delimiter NVARCHAR(1)
	SET @v_delimiter = '^' 
	DECLARE @max_loop_cnt		INTEGER = 0; 
	DECLARE @mst_loop_cnt		INTEGER = 0;
	
	-- LOG 용 변수 설정
    DECLARE @v_program_name NVARCHAR(150) = 'SCP0009_SAVE_ANL_SHIPMENT_PLAN_FG_FIX';
    DECLARE @v_log_type     NVARCHAR(30); -- START/END/ERROR/...
    DECLARE @n_log_count    INTEGER = 0;
    DECLARE @v_log_message  NVARCHAR(1000);
    DECLARE @v_description  NVARCHAR(500);
    DECLARE @d_event_date   DATETIME;

	BEGIN TRY
			-- 시작 LOG
		SET @v_log_type = 'START';
		SET @v_log_message = '########## Start of procedure ##########';
		SET @v_description = '';
		SET @d_event_date = SYSDATETIME();
		EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;

		-- 프로시저 LOOP 길이를 판단
		SET @max_loop_cnt = [dbo].[SCM_ARR_SPL_CNT](@p_active_flag, @v_delimiter);    
		
		WHILE LEN(@recv_active_flag) > 0 AND @mst_loop_cnt < @max_loop_cnt
		BEGIN
			-- @mst_loop_cnt 1증가
			SET @mst_loop_cnt = @mst_loop_cnt + 1;
			--SELECT @mst_loop_cnt,'@mst_loop_cnt'		

			-- 각 컬럼들에 대한 스플릿처리로직 스타트
			BEGIN
				SET @v_active_flag	= [dbo].[SCM_ARR_SPL_VAL](@p_active_flag    , @v_delimiter , @mst_loop_cnt) ;    
				SET @v_division_id	= [dbo].[SCM_ARR_SPL_VAL](@p_division_id    , @v_delimiter , @mst_loop_cnt) ; 
				SET @v_biz_type		= [dbo].[SCM_ARR_SP

L_VAL](@p_biz_type		, @v_delimiter , @mst_loop_cnt) ; 
				SET @v_item_id		= [dbo].[SCM_ARR_SPL_VAL](@p_item_id        , @v_delimiter , @mst_loop_cnt) ;    
				SET @v_to_site		= [dbo].[SCM_ARR_SPL_VAL](@p_to_site		, @v_delimiter , @mst_loop_cnt) ; 
				SET @v_from_site    = [dbo].[SCM_ARR_SPL_VAL](@p_from_site		, @v_delimiter , @mst_loop_cnt) ; 
				SET @v_project_code = [dbo].[SCM_ARR_SPL_VAL](@p_project_code   , @v_delimiter , @mst_loop_cnt) ; 
				SET @v_incoterms    = [dbo].[SCM_ARR_SPL_VAL](@p_incoterms		, @v_delimiter , @mst_loop_cnt) ; 
				SET @v_bod_id		= [dbo].[SCM_ARR_SPL_VAL](@p_bod_id			, @v_delimiter , @mst_loop_cnt) ; 
				SET @v_yyyymmdd     = [dbo].[SCM_ARR_SPL_VAL](@p_yyyymmdd       , @v_delimiter , @mst_loop_cnt) ; 
				SET @v_qty          = [dbo].[SCM_ARR_SPL_VAL](@p_qty            , @v_delimiter , @mst_loop_cnt) ; 
				SET @v_origin_from_division_id	= [dbo].[SCM_ARR_SPL_VAL](@p_origin_from_division_id    , @v_delimiter , @mst_loop_cnt) ; 
				SET @v_origin_to_division_id	= [dbo].[SCM_ARR_SPL_VAL](@p_origin_to_division_id      , @v_delimiter , @mst_loop_cnt) ; 
				SET @v_electrode_type			= [dbo].[SCM_ARR_SPL_VAL](@p_electrode_type				, @v_delimiter , @mst_loop_cnt) ;
				SET @v_fix_reason   = @p_fix_reason ; 	
			END
			IF(@debug_mode ='T')
			BEGIN
				PRINT '@mst_loop_cnt     ='+CONVERT(VARCHAR,@mst_loop_cnt)     ;
				PRINT '================================================='  ;
				PRINT '@v_active_flag     ='''+@v_active_flag     +'''';
				PRINT '@v_division_id     ='''+@v_division_id     +'''';
				PRINT '@v_biz_type ='''+@v_biz_type +'''';
				PRINT '@v_item_id         ='''+@v_item_id         +'''';
				PRINT '@v_to_site    ='''+@v_to_site    +'''';
				PRINT '@v_from_site    ='''+@v_from_site    +'''';
				PRINT '@v_project_code         ='''+@v_project_code         +'''';
				PRINT '@v_incoterms         ='''+@v_incoterms         +'''';
				PRINT '@v_bod_id         ='''+@v_bod_id         +'''';
				PRINT '@v_yyyymmdd        ='''+@v_yyyymmdd        +'''';
				PRINT '@v_qty             ='''+@v_qty             +'''';
				PRINT '@v_origin_from_division_id             ='''+ @v_origin_from_division_id             +'''';
				PRINT '@v_origin_to_division_id             ='''+ @v_origin_to_division_id             +'''';
				PRINT '@v_electrode_type             ='''+ @v_electrode_type             +'''';
				PRINT '@v_fix_reason      ='''+@v_fix_reason      +'''';
				PRINT '@p_user_id ='''+@p_user_id +'''';
			END;

			-- 기존 데이타 존재여부 조회
			DECLARE @v_pk_cnt INT=0;

			SELECT @v_pk_cnt = COUNT(*)
			FROM SCP_ANL_SHIPMENT_PLAN_FIX A
			WHERE 1=1
				AND A.division_id	= @v_division_id
				and a.BIZ_TYPE		= @v_biz_type
				and a.ITEM_ID		= @v_item_id
				and a.TO_SITE       = @v_to_site
				and a.FROM_SITE     = @v_from_site
				and a.PROJECT_CODE  = @v_project_code
				and a.INCOTERMS		= @v_incoterms
				and a.BOD_ID		= @v_bod_id
				and a.yyyymmdd      = @v_yyyymmdd
				and a.ORIGIN_FROM_DIVISION_ID	= @v_origin_from_division_id
				and a.ORIGIN_TO_DIVISION_ID		= @v_origin_to_division_id
				and a.ELECTRODE_TYPE		    = @v_electrode_type
			;

			PRINT '@v_pk_cnt =' + CONVERT(VARCHAR, @v_pk_cnt);

			-- 입력, 수정 모드 결정
			IF( @v_active_flag !='D' )
			BEGIN
				IF( @v_pk_cnt >0 )
					SET @v_active_flag ='M';
				ELSE
					SET @v_active_flag ='I';
			END;

