							UPDATE #SHIPMENT_EXIST_INFO 
							   SET REMARK = 'Y'
							 WHERE DAYOFWEEK_CD = @ROW_CNT
							   AND EXIST_YN = 'Y'
							   AND CALENDAR_MONTH = @v_mm
						    
						    SET @ROW_CNT = @ROW_CNT + 1;
						    
						    IF @ROW_CNT = 7
						    BEGIN
							   SET @ROW_CNT  = 1
							END
							
							SELECT @ALL_CNT = COUNT(*) FROM #SHIPMENT_EXIST_INFO WHERE REMARK = 'Y';
							
							IF @ALL_CNT = @ship_days
							BEGIN								
								UPDATE #SHIPMENT_EXIST_INFO 
								   SET REMARK = 'N'
								 WHERE REMARK = ''	
								
								BREAK;
							END								
						END
					END
				ELSE
					BEGIN
						SET @v_c = CASE WHEN @v_a = 0 THEN @p_qty / @ship_days ELSE (@p_qty-@v_a)/ @ship_days END
					END				
				
				SET @v_sum = @v_a + @v_c;
				SET @v_na  = @v_a;
				SET @v_mo  = @v_c;
			
				BEGIN
					SET @mEXEC = '';
					SET @mEXEC = @mEXEC+'INSERT INTO #LAST_INFO_TABLE '+CHAR(10);
					SET @mEXEC = @mEXEC+'SELECT (CASE WHEN Y.TRANSPORT_MODE = ''TRK'' THEN Y.DAYOFWEEK_CD ELSE Y.LT_WEEK END) AS LT_WEEK '+CHAR(10);
					SET @mEXEC = @mEXEC+'	   ,Y.EXIST_YN '+CHAR(10);
					SET @mEXEC = @mEXEC+'	   ,BASIS_YYYYMMDD '+CHAR(10);
					IF @ship_count = 1
						BEGIN
							SET @mEXEC = @mEXEC+'	   ,CASE WHEN DAYOFWEEK_CD = 2 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
						    SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 3 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
						    SET @mEXEC = @mEXEC+'     		 WHEN DAYOFWEEK_CD = 4 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
						    SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 5 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
						    SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 6 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
						    SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 7 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
						    SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 1 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
						    SET @mEXEC = @mEXEC+'	    ELSE 0 END QTY '+CHAR(10);						
						END
					ELSE IF @ship_count = 0
						BEGIN
							SET @mEXEC = @mEXEC+'	   ,CASE WHEN DAYOFWEEK_CD = 2 THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
							SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 3 THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
							SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 4 THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
							SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 5 THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
							SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 6 THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
							SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 7 THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
							SET @mEXEC = @mEXEC+'	   	     WHEN DAYOFWEEK_CD = 1 THEN CASE WHEN Y.CALENDA

R_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE 0 END ELSE 0 END '+CHAR(10);
							SET @mEXEC = @mEXEC+'	   	ELSE 0 END QTY '+CHAR(10);
						END
					ELSE
						BEGIN
							--lotsize 가 입력 수량보다 큰 경우 Remark = 'Y' 로 분배
							IF @ship_count <> @ship_days
								BEGIN
									SET @mEXEC = @mEXEC+'	   ,CASE WHEN DAYOFWEEK_CD = 2 THEN CASE WHEN REMARK = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE '+@v_sum+' END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 3 THEN CASE WHEN REMARK = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 4 THEN CASE WHEN REMARK = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 5 THEN CASE WHEN REMARK = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 6 THEN CASE WHEN REMARK = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 7 THEN CASE WHEN REMARK = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 1 THEN CASE WHEN REMARK = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);					
									SET @mEXEC = @mEXEC+'	    ELSE 0 END QTY '+CHAR(10);
								END
							ELSE
								BEGIN
									SET @mEXEC = @mEXEC+'	   ,CASE WHEN DAYOFWEEK_CD = 2 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE '+@v_sum+' END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 3 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 4 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 5 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 6 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 7 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);
									SET @mEXEC = @mEXEC+'	  		 WHEN DAYOFWEEK_CD = 1 THEN CASE WHEN EXIST_YN = ''Y'' THEN CASE WHEN Y.CALENDAR_MONTH = '+@v_mm+' THEN CASE WHEN SEQ = 1 THEN '+@v_sum+' ELSE '+@v_mo+' END ELSE 0 END ELSE 0 END '+CHAR(10);					
									SET @mEXEC = @mEXEC+'	    ELSE 0 END QTY '+CHAR(10);
								END							
						END
					SET @mEXEC = @mEXEC+'	   ,DIVISION_ID '+CHAR(10);
					SET @mEXEC = @mEXEC+'	   ,BOD_ID '+CHAR(10);
					SET @mEXEC = @mEXEC+'	   ,ITEM_ID '+CHAR(10);
					SET @mEXEC = @mEXEC+'	   ,PROJECT_CODE '+CHAR(10);
					SET @mEXEC = @mEXEC+'	   ,PLAN_TYPE '+CHAR(10);
					SET @mEXEC = @mEXEC+'	   ,PLAN_STA

RT_YYYYMMDD '+CHAR(10);
					SET @mEXEC = @mEXEC+'  FROM (SELECT X.EXIST_YN '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,X.REMARK '+CHAR(10);
				  	SET @mEXEC = @mEXEC+'			  ,X.DAYOFWEEK_CD '+CHAR(10);
				  	SET @mEXEC = @mEXEC+'			  ,X.SHIP_LT_TOTAL '+CHAR(10);
				  	SET @mEXEC = @mEXEC+'			  ,CASE WHEN CONVERT(INT, X.DAYOFWEEK_CD) <= (X.SHIP_LT_TOTAL % 7) THEN (7 + CONVERT(INT, X.DAYOFWEEK_CD)) - (X.SHIP_LT_TOTAL % 7) '+CHAR(10);
				   	SET @mEXEC = @mEXEC+'							ELSE CONVERT(INT, X.DAYOFWEEK_CD) - (X.SHIP_LT_TOTAL % 7) END LT_WEEK '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,X.TRANSPORT_MODE '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,X.DIVISION_ID '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,X.BOD_ID '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,X.FROM_SITE '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,X.TO_SITE '+CHAR(10);
				  	SET @mEXEC = @mEXEC+'			  ,K.BASIS_YYYYMMDD '+CHAR(10);
				  	SET @mEXEC = @mEXEC+'			  ,K.CALENDAR_MONTH '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,'''+@p_item_id+''' ITEM_ID '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,'''+@p_project_code+''' PROJECT_CODE '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,'''+@p_plan_type+''' PLAN_TYPE '+CHAR(10);
					SET @mEXEC = @mEXEC+'			  ,'''+@p_plan_start_yyyymmdd+''' PLAN_START_YYYYMMDD '+CHAR(10);
				  	SET @mEXEC = @mEXEC+'			  ,ROW_NUMBER() OVER(PARTITION BY X.CALENDAR_MONTH ORDER BY  (SELECT 1)) SEQ '+CHAR(10);
			  		SET @mEXEC = @mEXEC+'	     FROM #SHIPMENT_EXIST_INFO X '+CHAR(10);
					SET @mEXEC = @mEXEC+'			INNER JOIN (SELECT * FROM [dbo].[scm_sys_calendar_m] '+CHAR(10);
					SET @mEXEC = @mEXEC+'				 				WHERE ISO_YYYYWW = '''+@v_yyyyWW+''' ) K  ON X.DAYOFWEEK_CD = K.DAYOFWEEK_NO '+CHAR(10);
					SET @mEXEC = @mEXEC+'		  WHERE X.CALENDAR_MONTH = '''+@v_mm+''' '+CHAR(10);
					SET @mEXEC = @mEXEC+'	) Y '+CHAR(10);
					--ORDER BY Y.LT_WEEK ;   

				EXEC (@mEXEC);
				END
				
				--Daily Update.
			    UPDATE A
				   SET A.QTY = B.QTY
				   	 , A.LAST_UPDATE_DATE = CASE WHEN @v_creation_date IS NULL THEN GETDATE() ELSE @v_creation_date END
				     , A.LAST_UPDATED_BY = @p_last_updated_by
				  FROM SCP_ANL_SHIPMENT_PLAN_FG A, #LAST_INFO_TABLE B
				 WHERE 1=1
				   AND A.YYYYMMDD  = B.BASIS_YYYYMMDD 
				   AND A.DIVISION_ID = B.DIVISION_ID 
				   AND A.BOD_ID = B.BOD_ID 
				   AND A.PLAN_TYPE = B.PLAN_TYPE
                   AND A.SEQ = @p_seq
				   AND A.PLAN_START_YYYYMMDD  = B.PLAN_START_YYYYMMDD
				   AND A.PROJECT_CODE = B.PROJECT_CODE 
				   AND A.ITEM_ID = B.ITEM_ID 
				   AND A.MEASURE = 'SHIP_PLAN_AMEND'
		
				-- FIX수량 UPDATE
				UPDATE A
				SET A.qty				= B.QTY
					,A.last_updated_by	= @p_last_updated_by
					,A.last_update_date	= CASE WHEN @v_creation_date IS NULL THEN GETDATE() ELSE @v_creation_date END
				FROM SCP_ANL_SHIPMENT_PLAN_FIX A, #LAST_INFO_TABLE B
				WHERE A.division_id				= B.DIVISION_ID
				and A.ITEM_ID					= B.ITEM_ID
				and A.PROJECT_CODE				= B.PROJECT_CODE
				and A.BOD_ID					= B.BOD_ID
				and A.yyyymmdd					= B.BASIS_YYYYMMDD
				--and A.BIZ_TYPE					= B.p_biz_type
				--and A.TO_SITE					= B.p_to_site
				--and A.FROM_SITE					= B.p_from_site
				--and A.INCOTERMS					= B.p_incoterms
				--AND A.ORIGIN_FROM_DIVISION_ID	= B.p_origin_from_division_id
				--AND A.ORIGIN_TO_DIVISION_ID		= B.p_origin_to_division_id
				--AND ISNULL(NULLIF(A.ELECTRODE_TYPE,''),'-') = ISNULL(NULLIF(B.p_electrode_type,''),'-')				   

			 	FETCH NEXT FROM CUR INTO @p_division_id, @p_item_id, @p_from_site, @p_to_site, @p_project_code, @p_qty, @p_plan_type, @p_bod_id
									, @p_plan_start_yyyymmdd, @p_seq, @p_yyyymmdd, @p_trans_mode, @p_last_updated_by
			END
			CLOSE CUR
			DEALLOCATE CUR		
				   
			-- 5. FIX이력저장
			EXEC [dbo].[PR_SCP_ANL_SHIPMENT_PLAN_FG_FIX_HIST_DATASET] @SCP0009
			
			-- 6. 이력저장
			EXEC [dbo].[PR_SCP_ANL_SHIPMENT_PLAN_FG_HIST_DATASET] @SCP0009
			
		COMMIT;			
		END

		SET @v_exec_time  =  REPLICATE('0', 2 - LEN((convert

(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) + ':' +     
							 REPLICATE('0', 2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60)) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60))    

		SET @v_log_type = 'END';
		SET @v_log_message = '########## END of procedure ##########';
		SET @v_description  = N'[' + @v_exec_time + ']';   
		SET @d_event_date = SYSDATETIME();

		EXEC PR_SCM_SYS_LOG_BATCH_CALL_TRAN @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
		
		-- 결과코드, 결과 카운트 반환
		SELECT  'S' AS result_code,  @max_loop_cnt AS result_cnt ;

	END TRY

	BEGIN CATCH 
		BEGIN
			if (xact_state() <> 0) ROLLBACK TRAN; --입력 데이타 롤백 처리
						
			INSERT INTO scm_sys_log_batch (program_name,log_type,log_count,log_message,description,event_date,creation_date,created_by,last_update_date,last_updated_by)
			VALUES (ERROR_PROCEDURE(),'ERROR',NULL,ERROR_MESSAGE(),NULL,SYSDATETIME(),SYSDATETIME(),ERROR_PROCEDURE(),SYSDATETIME(),ERROR_PROCEDURE());

			-- error코드, errror 메시지 반환
			SELECT 'F' AS result_code, '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE() AS err_message ;

		END;
	END CATCH;

	IF OBJECT_ID('tempdb..#TblDynamic_SCP0009') IS NOT NULL	
		DROP TABLE #TblDynamic_SCP0009
	IF OBJECT_ID('tempdb..#LAST_INFO_TABLE') IS NOT NULL	
		DROP TABLE #LAST_INFO_TABLE 			

END

저장
			EXEC [dbo].[PR_SCP_ANL_SHIPMENT_PLAN_FG_HIST_DATASET] @SCP0009
			
		COMMIT;			
		END

		SET @v_exec_time  =  REPLICATE('0', 2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) + ':' +     
							 REPLICATE('0', 2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60)) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60))    

		SET @v_log_type = 'END';
		SET @v_log_message = '########## END of procedure ##########';
		SET @v_description  = N'[' + @v_exec_time + ']';   
		SET @d_event_date = SYSDATETIME();

		EXEC PR_SCM_SYS_LOG_BATCH_CALL_TRAN @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
		
		-- 결과코드, 결과 카운트 반환
		SELECT  'S' AS result_code,  @max_loop_cnt AS result_cnt ;

	END TRY

	BEGIN CATCH 
		BEGIN
			if (xact_state() <> 0) ROLLBACK TRAN; --입력 데이타 롤백 처리
						
			INSERT INTO scm_sys_log_batch (program_name,log_type,log_count,log_message,description,event_date,creation_date,created_by,last_update_date,last_updated_by)
			VALUES (ERROR_PROCEDURE(),'ERROR',NULL,ERROR_MESSAGE(),NULL,SYSDATETIME(),SYSDATETIME(),ERROR_PROCEDURE(),SYSDATETIME(),ERROR_PROCEDURE());

			-- error코드, errror 메시지 반환
			SELECT 'F' AS result_code, '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE() AS err_message ;

		END;
	END CATCH;

	IF OBJECT_ID('tempdb..#TblDynamic_SCP0009') IS NOT NULL	
		DROP TABLE #TblDynamic_SCP0009
	IF OBJECT_ID('tempdb..#LAST_INFO_TABLE') IS NOT NULL	
		DROP TABLE #LAST_INFO_TABLE 			

END

/*
 * Program ID   : SCP0009_SAVE_ANL_SHIPMENT_PLAN_FG_WEEKLY
 * Description  : ANL SHIPMENT PLAN FG save
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2022/09/07	jahn1501		PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - 주차별 수량 입력
 * 2022-12/01   jahn1501        PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - Parial Weekly 수량 입력 가능하도록 변경
 * 2024-07/04   mrchois         PJ20244573 / LGES SCM SCP 생산모델 기반 공급계획 수립체계 구성		- Weekly로 저장 시에 연도가 바뀌는 W01주차에 정상저장 되도록 변경
 * 
 */
CREATE PROCEDURE [dbo].[SCP0009_SAVE_ANL_SHIPMENT_PLAN_FG_WEEKLY]
	@SCP0009			AS DBO.SCP0009       READONLY
AS

BEGIN
	SET NOCOUNT ON;
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
	
	DECLARE @max_loop_cnt		NVARCHAR(50);
	
	-- LOG 용 변수 설정
    DECLARE @v_program_name NVARCHAR(150) = 'SCP0009_SAVE_ANL_SHIPMENT_PLAN_FG_WEEKLY';
    DECLARE @v_log_type     NVARCHAR(30); -- START/END/ERROR/...
    DECLARE @n_log_count    INTEGER = 0;
    DECLARE @v_log_message  NVARCHAR(1000);
    DECLARE @v_description  NVARCHAR(500);
    DECLARE @d_event_date   DATETIME;

	-- 예외처리 변수 설정
	DECLARE @v_err_code  INTEGER;
	DECLARE @v_err_message  NVARCHAR(4000)='';
	
	DECLARE @v_time_zone  NVARCHAR(100);
	DECLARE @v_creation_date		datetime;		-- timezone에 따른 저장위해서

	-- 실행시간 확인용    
    DECLARE @v_start_time   DATETIME     = SYSDATETIME();    
    DECLARE @v_exec_time    NVARCHAR(10) = ''--'00:00';  
    
    DECLARE @v_bucket		NVARCHAR(50) = ''
	DECLARE @mEXEC NVARCHAR(MAX);

	/********************************************************************************
	* 임시테이블만들기
	********************************************************************************/
	IF OBJECT_ID('tempdb..#TblDynamic_SCP0009') IS NOT NULL	
		DROP TABLE #TblDynamic_SCP0009
	IF OBJECT_ID('tempdb..#LAST_INFO_TABLE') IS NOT NULL	
		DROP TABLE #LAST_INFO_TABLE 		

	CREATE TABLE #TblDynamic_SCP0009 (
		A	nvarchar(1),
		p_active_flag			nvarchar(1),
		p_division_id			nvarchar(30),
		p_plan_start_yyyymmdd	nvarchar(8),
		p_plan_type				nvarchar(2),
		p_seq					nvarchar(10),
		p_biz_type				nvarchar(1),
		p_project_code			nvarchar(100),
		p_item_id				nvarchar(100),
		p_to_site				nvarchar(100),
		p_incoterms				nvarchar(20),
		p_from_site				nvarchar(50),
		p_bod_id				nvarchar(50),
		p_measure				nvarchar(100),
		p_yyyymmdd				nvarchar(8),
		p_qty					nvarchar(200),
		p_origin_from_division_id	nvarchar(30),
		p_origin_to_division_id		nvarchar(30),
		p_electrode_type		nvarchar(50),
		p_created_by			nvarchar(150),
		p_last_updated_by		nvarchar(150),
		p_time_zone				nvarchar(100),
		p_cplt_flag				nvarchar(1)
	);

	CREATE TABLE #LAST_INFO_TABLE (
		LT_WEEK					nvarchar(10),
		EXIST_YN				nvarchar(1),
		BASIS_YYYYMMDD			nvarchar(8),
		QTY						NUMERIC(20,10),--INT,
		DIVISION_ID				nvarchar(50),
		BOD_ID					nvarchar(50),
		ITEM_ID					nvarchar(200),
		PROJECT_CODE			nvarchar(100),
		PLAN_TYPE				nvarchar(100),
		PLAN_START_YYYYMMDD		nvarchar(20),
	);

	-- 트렌젝션 시작
	BEGIN TRAN;
	BEGIN TRY

		-- 시작 LOG
		SET @v_log_type = 'START';
		SET @v_log_message = '########## Start of procedure ##########';
		SET @v_description = '';
		SET @d_event_date = SYSDATETIME();

		EXEC PR_SCM_SYS_LOG_BATCH_CALL_TRAN @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;

  
		SET @v_bucket = (SELECT TOP 1 p_bucket_type FROM @SCP0009) 
								
		IF @v_bucket = 'DAILY'
		BEGIN
			--TimeZone set
			SET @v_time_zone = (SELECT TOP 1 p_time_zone
								FROM @SCP0009  
								)
			;
			IF (@v_time_zone=NULL OR @v_time_zone='')
				SET @v_time_zone = 'AS054'
			;

			SET @v_creation_date    = [dbo].[FN_MULTY_TIME](@v_time_zone); 

			-- 임시테이블 데이타 생성
			INSERT IN

p_chk_all				NVARCHAR(1), -- 2021.11.24 :  체크 시 bucket='daily' 조회
	@p_program_id			NVARCHAR(10) = 'SCP0009' ,
	@p_sheet_name			NVARCHAR(30) = 'Shipment Plan FG' ,
	@p_user_id				NVARCHAR(30),
	@debug_mode             NVARCHAR(1) ='F'
AS
BEGIN
	SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
	SET NOCOUNT ON; 



	--DECLARE @p_from_yyyymmdd		NVARCHAR(8)		= N'20240101';
	--DECLARE @p_to_yyyymmdd			NVARCHAR(8)		= N'20250223';
	--DECLARE @p_division_id			NVARCHAR(10)	= N'40';
	--DECLARE @p_biz_type				NVARCHAR(10)	= N'P';
	--DECLARE @p_project_code			NVARCHAR(max)	= N'';
	--DECLARE @p_item_id				NVARCHAR(max)	= N'';
	--DECLARE @p_electype				NVARCHAR(30)	= N'';
	--DECLARE @p_plan_start_yyyymmdd	NVARCHAR(8)		= N'20240226';
	--DECLARE @p_plan_type			NVARCHAR(50)	= N'MA';
	--DECLARE @p_seq					NVARCHAR(50)	= N'1';
	--DECLARE @p_fromsite				NVARCHAR(MAX)	= N'';
	--DECLARE @p_team_id				NVARCHAR(MAX)	= N'';
	--DECLARE @p_tosite				NVARCHAR(MAX)	= N'';
	--DECLARE @p_bucket				NVARCHAR(30)	= N'DAILY';
 --   DECLARE @p_to_period			NVARCHAR(8)		= N'20250223';
	--DECLARE @p_chk_all				NVARCHAR(1)		= N'N';
	--DECLARE @p_program_id			NVARCHAR(30)	= N'SCP0009';
	--DECLARE @p_sheet_name			NVARCHAR(30)	= N'Shipment Plan FG';
	--DECLARE @p_user_id				NVARCHAR(30)	= N'iamarock';
	--DECLARE @debug_mode				NVARCHAR(1)		= N'F';


    DECLARE @V_ELAPSED_TIME_BEG             DATETIME            = CURRENT_TIMESTAMP;


	declare @v_data_cnt nvarchar(8);
	set @v_data_cnt =0;

	DECLARE @v_cnt_usr_measure	INTEGER =0;
	DECLARE @v_from_yyyymmdd     AS NVARCHAR(8);
	DECLARE @v_to_yyyymmdd       AS NVARCHAR(8);
	DECLARE @v_from_result       AS NVARCHAR(8);
	DECLARE @v_to_result         AS NVARCHAR(8);
	DECLARE @v_min_yyyymmdd      AS NVARCHAR(8);   -- 2021/07/21	
	DECLARE @v_RSLT_FLAG AS NVARCHAR(1) = 'Y';   -- 2021/07/21
	DECLARE @DIV_ENERGY  AS NVARCHAR(MAX) = '82';

	SET @v_cnt_usr_measure = (
								SELECT COUNT(*)
								FROM scm_mst_titleset_user
								WHERE 1=1
								 AND program_id  =  @p_program_id
								 AND sheet_name  =  @p_sheet_name
								 AND user_id     =  @p_user_id
							  )    

	SET @v_from_yyyymmdd = '';
	SET @v_to_yyyymmdd   = '';
	SET @v_from_result   = '';
	SET @v_to_result     = '';

	  SELECT @v_from_yyyymmdd = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_plan_start_yyyymmdd

	  SELECT @v_from_result = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_from_yyyymmdd;

	  SELECT @v_to_result = C.BASIS_START_DATE
	  FROM   [dbo].[SCM_SYS_CALENDAR_M]      C
	  WHERE  1 = 1
	  AND    C.BASIS_YYYYMMDD = @p_to_yyyymmdd;

	  IF @v_from_yyyymmdd > @v_from_result
		  BEGIN -- 실적 보여줌		  
		  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
		  SET @v_to_result     = @v_from_yyyymmdd;
		  END;
	  ELSE IF @v_from_yyyymmdd <= @v_from_result
		  BEGIN -- 실적 없음
		  
		  SET @v_RSLT_FLAG = 'N';  -- 2021/07/21 // 계획만 조회
		  
		  SET @v_to_yyyymmdd   = @p_to_yyyymmdd;
		  SET @v_from_result = CONVERT(CHAR(8), DATEADD(MM, 6, convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_to_result = CONVERT(CHAR(8), DATEADD(MM, -6, convert(datetime,@p_plan_start_yyyymmdd)), 112)
		  END;
	  ELSE IF @v_from_yyyymmdd > @v_to_result
		  BEGIN
		  SET @v_from_yyyymmdd = CONVERT(CHAR(8), DATEADD(MM, -6,  convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_to_yyyymmdd = CONVERT(CHAR(8), DATEADD(MM, -6,  convert(datetime,@p_plan_start_yyyymmdd)), 112);
		  SET @v_from_result = @p_from_yyyymmdd;
		  SET @v_to_result = @p_to_yyyymmdd;
		  END;
	  ELSE IF @v_from_yyyymmdd = @v_to_result
		  BEGIN
		  SET @v_to_yyyymmdd = @v_from_yyyymmdd
		  SET @v_from_result = @p_from_yyyymmdd;
		  SET @v_to_result = @p_to_yyyymmdd;
		  END;

	 IF @debug_mode ='T'
		BEGIN
			PRINT '----------------------------------';
			PRINT 'v_from_yyyymmdd

yyyymmdd  BETWEEN @p_from_yyyymmdd AND @p_to_yyyymmdd
					GROUP BY a.basis_yyyymm, a.month_name

					UNION ALL

					SELECT 'D_'+a.basis_yyyymmdd   AS yyyymmdd
							, a.basis_yyyymmdd + CONVERT(CHAR(2), 31) AS sort_order_no
						FROM [dbo].[scm_sys_calendar_m] a
					WHERE a.basis_yyyymmdd  BETWEEN @p_from_yyyymmdd AND @p_to_yyyymmdd
					  AND @p_bucket = 'DAILY'	--2021/10/05 : UI 속도 개선
					GROUP BY a.basis_yyyymmdd

				) AS A
			ORDER BY sort_order_no  ;

			SET @mEXEC = '';

			-- 20230411 ENERGY (UI 셀병합 위해서 문자열 AND Null일 경우 공백으로 처리 필요)
			SET @mEXEC = @mEXEC+'      ;WITH W_ENERGY AS (
			                                              SELECT ITEM_ID 
														       , convert(nvarchar(max), Convert(numeric(13,4),MAX(ENERGE))) AS ENERGY 
															FROM SCM_ITEM_M_SN WITH(NOLOCK)  
														   WHERE ENERGE IS NOT NULL 
														     AND ENERGE != '''' 
													    GROUP BY ITEM_ID)		
						'+CHAR(10); 
			SET @mEXEC = @mEXEC+'      SELECT a.*																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , ISNULL(b.PROJECT_NAME, ''-'') PROJECT_NAME								'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , ISNULL(EG.ENERGY,'' '') AS ENERGY								                        '+CHAR(10);	
			--@p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'			  , ISNULL(CASE WHEN a.division_id <> ''40'' and a.division_id <> ''82'' THEN b.PROJECT_OWNER ELSE f.USER_NAME_EN end, ''-'') AS PROJECT_OWNER												'+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+'			  , ISNULL(CASE WHEN a.origin_to_division_id <> ''40'' and a.division_id <> ''82'' THEN b.PROJECT_OWNER ELSE f.USER_NAME_EN end, ''-'') AS PROJECT_OWNER												'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , CASE WHEN c.ITEM_TYPE IS NULL OR c.ITEM_TYPE = '''' THEN ''-'' ELSE dbo.FN_GET_LOOKUP_CODE_DESC(''ITEM_TYPE_CODE'', c.ITEM_TYPE) END ITEM_TYPE		'+CHAR(10);
			SET @mEXEC = @mEXEC+'			  , ISNULL(g.DEPT_NAME_KO, ''-'') DEPT_NAME_KO								'+CHAR(10);
			IF @p_division_id IN ('40')
			BEGIN
				SET @mEXEC = @mEXEC+'			  , ISNULL(c.CELL_TYPE, ''-'') PRODUCT_GROUP								'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(e.ATTRIBUTE5, ''-'') CELL_MODEL									'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , CAST(ISNULL(k.CELL_PACK_COUNT, 0) AS INT) CELL_PACK_COUNT				'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(e.Application, ''-'') APPLICATION								'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.MIN_CAPACITY, ''-'') MIN_CAPACITY								'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(d.SOLDTO_CUSTOMER, ''-'') SOLDTO_CUSTOMER						'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.FORECAST_INFO_SPEC, ''-'') MODEL_SPEC							'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.FORECAST_INFOR_VERSION, ''-'') MODEL_VERSION					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ISNULL(k.FORECAST_INFO_ALL, ''-'') SPEC_VERSION							'+CHAR(10);			
			END
			ELSE
			BEGIN
				SET @mEXEC = @mEXEC+'			  , ''-'' PRODUCT_GROUP														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' CELL_MODEL														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , 0 CELL_PACK_COUNT														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' APPLICATION														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' MIN_CAPACITY														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' SOLDTO_CUSTOMER													'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' MODEL_SPEC														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' MODEL_VERSION														'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  , ''-'' SPEC_VERSION														'+CHAR(10);	
			END		
			SET @mEXEC = @mEXEC+'	   from (																			'+CHAR(10);

			SET @mEXEC = @mEXEC+'      SELECT																			'+CHAR(10);
			SET @mEXEC = @mEXEC+'      		  key_idx																	'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, division_id

				'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, biz_type																	'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, dbo.FN_GET_LOOKUP_CODE_DESC(''BIZ_TYPE'', BIZ_TYPE) AS biz_type_name		'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, project_code																'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, item_id																	'+CHAR(10);
			SET @mEXEC = @mEXEC+'			,(SELECT TOP 1 isnull(NULLIF(NICK_NAME,''''),''-'') FROM DBO.SCM_MST_ITEM_SN x WITH(NOLOCK) WHERE 1=1 AND x.ITEM_ID = a.item_id)	nick_name '+CHAR(10);
			SET @mEXEC = @mEXEC+'			,(SELECT TOP 1 isnull(NULLIF(SCP_EXTRA_SPEC,''''),''-'') FROM DBO.SCM_MST_ITEM_SN x WITH(NOLOCK) WHERE 1=1 AND x.DIVISION_ID = a.DIVISION_ID AND x.ITEM_ID = a.item_id)	EXTRA_SPEC '+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, to_site, to_site2																						'+CHAR(10);
			
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'			,(select top 1 SITE_DESCRIPTION from SCM_MST_SITE  where 1=1  and SCM_SITE_ID = TO_SITE2) to_site_name '+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+' 			, to_site as to_site_name							'+CHAR(10);

			SET @mEXEC = @mEXEC+' 			, incoterms																						'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, from_site																						'+CHAR(10);
			SET @mEXEC = @mEXEC+'			,isnull((select top 1 SITE_DESCRIPTION from SCM_MST_SITE  where 1=1  and SCM_SITE_ID = FROM_SITE),''-'') from_site_name '+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, A.bod_id																						'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, A.BOD_FROM_YYYYMMDD																			'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, A.BOD_TO_YYYYMMDD																				'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, ISNULL(transport_mode , ''-'') as transport_mode												'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, ISNULL(lt_day , 0) as lt_day																	'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, origin_from_division_id, origin_to_division_id, electrode_type								'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, cast( round( [dbo].[FN_GET_SCP_ANL_BOH_QTY](division_id ,plan_start_yyyymmdd, plan_type, seq, to_site , item_id,from_yyyymmdd) , 1) as int) as boh '+CHAR(10);
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				BEGIN SET @mEXEC = @mEXEC+' 			, CONVERT(CHAR(10),DATEADD(DAY, (SELECT ISNULL(SHIP_FROZEN, 0) AS SHIP_FROZEN FROM SCM_MST_SITE WHERE DIVISION_ID= division_id AND SCM_SITE_ID=FROM_SITE) , CONVERT(DATE, '''+@p_plan_start_yyyymmdd+''', 112)), 23) AS SHIP_FROZEN '   +CHAR(10); END
			ELSE
				BEGIN SET @mEXEC = @mEXEC+' 			, CONVERT(CHAR(10),DATEADD(DAY, (SELECT ISNULL(SHIP_FROZEN, 0) AS SHIP_FROZEN FROM SCM_MST_SITE WHERE DIVISION_ID= origin_from_division_id AND SCM_SITE_ID=FROM_SITE) , CONVERT(DATE, '''+@p_plan_start_yyyymmdd+''', 112)), 23) AS SHIP_FROZEN '   +CHAR(10); END

			SET @mEXEC = @mEXEC+' 			, measure																						'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, measure_order_no																				'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, measure_label 																				'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			, plan_start_yyyymmdd, plan_type, seq, from_yyyymmdd,to_yyyymmdd								'+CHAR(10);
			SET @mEXEC = @mEXEC+' 			'+@mQry_sum
																							 +CHAR(10);
			--2021/10/05 : UI 속도 개선
			--IF(@v_RSLT_FLAG = 'Y')
			--BEGIN
				SET @mEXEC = @mEXEC+'       FROM #TMP_SCP0009_FNL_RSLT_PLAN  a																'+CHAR(10);
			--END
			--ELSE IF(@v_RSLT_FLAG = 'N')
			--BEGIN
			--	SET @mEXEC = @mEXEC+'       FROM #TMP_SCP0009_PLAN  a																		'+CHAR(10);
			--END
			-- BOD 2단계 개발
			--SET @mEXEC = @mEXEC+'	   GROUP BY key_idx, division_id, biz_type, project_code, item_id,to_site,to_site2,incoterms,  from_site,bod_id ,transport_mode, lt_day,origin_from_division_id, origin_to_division_id, electrode_type, measure,measure_order_no,measure_label ,

plan_start_yyyymmdd, plan_type, seq,from_yyyymmdd,to_yyyymmdd'+CHAR(10) ;
			SET @mEXEC = @mEXEC+'	   GROUP BY key_idx, division_id, biz_type, project_code, item_id,to_site,to_site2,incoterms,  from_site,bod_id ,transport_mode, lt_day,origin_from_division_id, origin_to_division_id, electrode_type, measure,measure_order_no,measure_label ,plan_start_yyyymmdd, plan_type, seq,from_yyyymmdd,to_yyyymmdd, BOD_FROM_YYYYMMDD, BOD_TO_YYYYMMDD '+CHAR(10) ;


			SET @mEXEC = @mEXEC+'      ) a																									'+CHAR(10);
			SET @mEXEC = @mEXEC+'      LEFT OUTER JOIN W_ENERGY	 EG  on a.ITEM_ID	= EG.ITEM_ID AND A.DIVISION_ID = '''+@DIV_ENERGY+''' 	'+CHAR(10); -- 20230411 ENERGY / only div = 82 ess
			SET @mEXEC = @mEXEC+'      LEFT OUTER JOIN (SELECT DIVISION_ID																	'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , PROJECT_CODE																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , PROJECT_NAME																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , PROJECT_OWNER																	'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, PROJECT_CODE ORDER BY PROJECT_VER_SEQ ASC ) NUMS											'+CHAR(10);
			SET @mEXEC = @mEXEC+'					FROM SCM_MST_PROJECT WITH(NOLOCK)														'+CHAR(10);
			SET @mEXEC = @mEXEC+'				 ) b  on a.PROJECT_CODE	= b.PROJECT_CODE 				'+CHAR(10);

			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				  AND a.DIVISION_ID	= b.DIVISION_ID 				'+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+'				  AND a.origin_to_division_id = b.DIVISION_ID 				'+CHAR(10);

			SET @mEXEC = @mEXEC+'					 and b.NUMS=1																			'+CHAR(10);
			SET @mEXEC = @mEXEC+'      LEFT JOIN (SELECT c1.DIVISION_ID																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.ITEM_ID																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.ITEM_NAME																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.NICK_NAME																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c1.ITEM_TYPE																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , c2.SEGMENT2 CELL_TYPE															'+CHAR(10);
			SET @mEXEC = @mEXEC+'						 , ROW_NUMBER() OVER ( PARTITION BY c1.DIVISION_ID, c1.ITEM_ID ORDER BY  CASE c1.ITEM_TYPE WHEN ''P'' THEN 999 WHEN ''H'' THEN 888 WHEN ''R'' THEN 777  WHEN ''Q'' THEN 666 ELSE 0 END  DESC ) NUMS																		'+CHAR(10);
			SET @mEXEC = @mEXEC+'					FROM SCM_MST_ITEM_SN c1 WITH(NOLOCK)													'+CHAR(10);
			SET @mEXEC = @mEXEC+'					LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL c2 WITH(NOLOCK)									'+CHAR(10);
			SET @mEXEC = @mEXEC+'					 ON c1.CELL_TYPE = c2.SEGMENT1 															'+CHAR(10);
			SET @mEXEC = @mEXEC+'					 AND c2.LOOKUP_TYPE = ''CELL_TYPE'' 													'+CHAR(10);
			SET @mEXEC = @mEXEC+'				 ) c  on a.item_id=c.item_id																'+CHAR(10);

			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				     and a.division_id=c.division_id																'+CHAR(10);
			ELSE
				SET @mEXEC = @mEXEC+'				     and a.origin_to_division_id=c.division_id																'+CHAR(10);
			SET @mEXEC = @mEXEC+'				     and c.nums=1																			'+CHAR(10);
			
			/*add start jahn1501*/
			IF @p_division_id IN ('40')
			BEGIN
				SET @mEXEC = @mEXEC+'      LEFT JOIN (SELECT DIVISION_ID																		'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , ITEM_ID																			'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_CELL_MODEL CELL_MODEL												'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_CELL_PACK_COUNT CELL_PACK_COUNT									'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , MIN_CAPACITY																		'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_SPEC																'+CHAR(10);
				SET @mEX

EC = @mEXEC+'						 , FORECAST_INFOR_VERSION															'+CHAR(10);
				SET @mEXEC = @mEXEC+'						 , FORECAST_INFO_SPEC + FORECAST_INFOR_VERSION AS FORECAST_INFO_ALL					'+CHAR(10);
				SET @mEXEC = @mEXEC+'					FROM DM_MST_ITEM_SINGLE_V WITH(NOLOCK)													'+CHAR(10);
				SET @mEXEC = @mEXEC+'				 ) k  on a.item_id=k.item_id																'+CHAR(10);
				SET @mEXEC = @mEXEC+'				     and a.division_id=k.division_id														'+CHAR(10);
			END
			/*end*/		
			/********** DEPT NAME START **********/
			SET @mEXEC = @mEXEC+'			LEFT JOIN SCM_MST_SITE d 					'+CHAR(10);
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
			BEGIN
				SET @mEXEC = @mEXEC+'			   ON d.division_id	= a.division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  AND d.SCM_SITE_ID	= a.TO_SITE 					'+CHAR(10);
			END
			ELSE
			BEGIN
				SET @mEXEC = @mEXEC+'			   on d.division_id	= a.origin_to_division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			  and d.scm_site_id	= a.TO_SITE2					'+CHAR(10);
			END
			SET @mEXEC = @mEXEC+'				  AND d.VALID_YN       = ''Y'' 					'+CHAR(10);


			SET @mEXEC = @mEXEC+'			LEFT JOIN SCM_MST_SITE_ITEM e 					'+CHAR(10);
			--IF @p_division_id NOT IN ('EE','EE_UC')
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
			BEGIN
				SET @mEXEC = @mEXEC+'			    on e.division_id	= a.division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			    and e.scm_site_id	= a.TO_SITE					'+CHAR(10);
			END
			ELSE
			BEGIN
				SET @mEXEC = @mEXEC+'			    on e.division_id	= a.origin_to_division_id 					'+CHAR(10);
				SET @mEXEC = @mEXEC+'			    and e.scm_site_id	= a.TO_SITE2					'+CHAR(10);
			END
			SET @mEXEC = @mEXEC+'					and e.project_code	= a.project_code 					'+CHAR(10);
			SET @mEXEC = @mEXEC+'					and e.item_id		= a.item_id 					'+CHAR(10);
			SET @mEXEC = @mEXEC+'					and e.VALID_YN		=''Y'' 					'+CHAR(10);

			SET @mEXEC = @mEXEC+'			LEFT JOIN [dbo].[SCM_MST_SSO_USER_INFO] f WITH(NOLOCK) 					'+CHAR(10);
			SET @mEXEC = @mEXEC+'				   ON  substring( e.OWNER, 0, case when charindex('','',e.OWNER) = 0 then len(e.OWNER)+1 else charindex('','',e.OWNER) end ) = f.USER_ID 					'+CHAR(10);
			
            -- 20241113 E20241105-000454 : 소형외 사업부도 소형과 동일하게 Site 의 부서 대신 Site Itme의 Owner 부서 기준으로 표시
			SET @mEXEC = @mEXEC+'			LEFT JOIN [dbo].[SCM_MST_SSO_DEPT_INFO] g WITH(NOLOCK) 					'+CHAR(10);

			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				   ON  f.DEPT_ID = g.DEPT_ID 					'+CHAR(10);
			ELSE 
				SET @mEXEC = @mEXEC+'				   ON  f.DEPT_ID = g.DEPT_ID 					'+CHAR(10);

		 /*
			IF @p_division_id NOT IN (SELECT DIVISION_ID FROM dbo.FN_GET_DIVISION_DIV('EE')) --div_commonization
				SET @mEXEC = @mEXEC+'				   ON  CASE WHEN a.DIVISION_ID = ''40'' THEN f.DEPT_ID ELSE d.DEPT_ID END  = g.DEPT_ID 					'+CHAR(10);
			ELSE 
				SET @mEXEC = @mEXEC+'				   ON  CASE WHEN a.origin_to_division_id = ''40'' THEN f.DEPT_ID ELSE d.DEPT_ID END  = g.DEPT_ID 					'+CHAR(10);
           */
	        IF NOT(@p_team_id  IS NULL   OR  @p_team_id = '') 
			BEGIN 
			    SET @mEXEC = @mEXEC+ ' WHERE 1=1 					'+CHAR(10);
			    SET @mEXEC = @mEXEC+ [dbo].[FN_SCM_GET_WHERE_SQL]('g.DEPT_ID', 'IN', @p_team_id) +CHAR(10);
			END;
			
			SET @mEXEC = @mEXEC+'      ORDER BY a.division_id, a.biz_type, a.item_id, a.to_site, project_code, a.incoterms, a.from_site, a.bod_id, a.measure_order_no		'+CHAR(10);


			SET @mEXEC = @mEXEC+' OPTION (HASH GROUP) ; '+CHAR(10);


